import contextlib,io,pytest
import game_server.games.ticktaktoe as live
Original=live.TikTakToe
observed=set()
class Probe(Original):
 def checkForWinner(self):
  result=super().checkForWinner()
  if self.xSize!=self.ySize and self.scoreLineLength>=3:
   k=self.scoreLineLength
   for dx,dy in ((1,0),(0,1),(1,1),(1,-1)):
    for y in range(self.ySize):
     for x in range(self.xSize):
      if 0<=x+(k-1)*dx<self.xSize and 0<=y+(k-1)*dy<self.ySize:
       line=[self.grid[y+i*dy][x+i*dx] for i in range(k)]
       if line[0] in (live.X,live.O) and all(v==line[0] for v in line):observed.add((dx,dy))
  return result
live.TikTakToe=Probe
output=io.StringIO()
with contextlib.redirect_stdout(output),contextlib.redirect_stderr(output):
 result=pytest.main(['-q','--tb=short','tests/test_gflo_rectangles.py'])
assert result==0,output.getvalue()
missing={(1,0),(0,1),(1,1),(1,-1)}-observed
assert not missing, 'Tests did not exercise K>=3 non-square winning boards in directions: '+repr(sorted(missing))
print('non-square-directions-ok')

